-- One-to-Many: Posts belong to Users
CREATE TABLE posts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  author_id UUID REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL
);

-- Many-to-Many: Posts have Tags (junction table)
CREATE TABLE tags (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT UNIQUE NOT NULL
);

CREATE TABLE post_tags (
  post_id UUID REFERENCES posts(id) ON DELETE CASCADE,
  tag_id UUID REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (post_id, tag_id)
);

-- BAD: Denormalized (data duplication)
CREATE TABLE orders_bad (
  id UUID PRIMARY KEY,
  customer_name TEXT,  -- Duplicated for every order!
  customer_email TEXT, -- Duplicated for every order!
  product_name TEXT,
  quantity INTEGER
);

-- GOOD: Normalized (reference by ID)
CREATE TABLE customers (
  id UUID PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL
);

CREATE TABLE orders_good (
  id UUID PRIMARY KEY,
  customer_id UUID REFERENCES customers(id),
  product_id UUID REFERENCES products(id),
  quantity INTEGER NOT NULL
);

